```python
def testRange(x):
  if x.val >= 0x8000 or x.val < -0x8000:
    mark('RISC-V: value too large')

def loadItemReg(x, r):
  if type(x) == Var:
    putMemOp('lw', r, x.reg, x.adr)
    releaseReg(x.reg)
  elif type(x) == Const:
    if str(x.val) == 'True':
