def S(self, k: int) -> tuple[int | None, int]:
    # S(c) ← « c := 0 » (Pair « c := c + 1 » / Other)*
    c = 0
    while k != None:
      r = k
      k = self.Pair(k)
      if k == None:
        k = self.Other(r)
      else:
        c += 1
    return (r, c)

  def Pair(self, k: int) -> int | None:
    # Pair ← aa !a
    k = self.literal(k, 'aa')
    if k != None:
      r = k
      k = self.literal(k, 'a')
      k = r if k == None else None
    return k

  def Other(self, k: int) -> int | None:
    # Other ← a+ / b+
    r = k
    k = self.literal(r, 'a')
    if k != None:
      while k != None:
        r = k
        k = self.literal(k, 'a')
      k = r
    if k == None:
      k = self.literal(r, 'b')
      if k != None:
        while k != None:
          r = k
          k = self.literal(k, 'b')
        k = r
    return k

  def parse(self, s: str) -> tuple[int | None, int]:
    self.src = s
    return self.S(0)
