"/"+"/"*        { if (!absolute && depth == 0) { int i; for(i=0;i<yyleng;i++) if(yytext[i]=='/') { absolute = true; break; } } }
^"/"[/]*        { absolute = true; }
{LONGCOMP}      { error("component too long"); }
{COMP}          { push_comp(yytext, yyleng); }
[^a-zA-Z0-9./ \t\n] { error("invalid character"); }
\n              { output_path(); }
