def factor():
  if SC.sym == IDENT:
    x = find(SC.val)
    if type(x) == Var:
      x = CG.genVar(x)
      getSym()
    elif type(x) == Const:
      x = Const(x.tp, x.val)
      x = CG.genConst(x)
      getSym()
    else:
      mark('variable or constant identifier expected')
    x = selector(x)
  elif SC.sym == NUMBER:
    x = Const(Int, SC.val)
    x = CG.genConst(x)
    getSym()
  elif SC.sym == LPAREN:
    getSym()
    x = expression()
    if SC.sym == RPAREN:
      getSym()
    else:
      mark(') expected')
  elif SC.sym == LBRACE:
    getSym()
    if SC.sym in FIRSTEXPRESSION:
      y = expression()
      if y.tp == Int:
        x = CG.genUnaryOp(SET, y)
      else:
        mark('not integer')
      while SC.sym == COMMA:
        getSym()
        y = expression()
        if y.tp == Int:
          y = CG.genUnaryOp(SET, y)
        else:
          mark('not integer')
        x = CG.genBinaryOp(UNION, x, y)
    else:
      x = Const(Set(0, 32), 0)
      x = CG.genConst(x)
    if SC.sym == RBRACE:
      getSym()
    else:
      mark('} expected')
  elif SC.sym == NOT:
    getSym()
    x = factor()
    if x.tp != Bool:
      mark('not boolean')
    elif type(x) == Const:
      x.val = 1 - x.val  # constant folding
    else:
      x = CG.genUnaryOp(NOT, x)
  elif SC.sym in {CARD, COMPLEMENT}:
    op = SC.sym
    getSym()
    x = factor()
    if type(x.tp) == Set:
      x = CG.genUnaryOp(op, x)
    else:
      mark('set expected')
  else:
    mark('expression expected')
  return x
