def selector(x):
  while SC.sym in {LBRAK, PERIOD}:
    if SC.sym == LBRAK:  #  x[y]
      getSym()
      y = expression()
      if type(x.tp) == Array:
        if y.tp == Int:
          if type(y) == Const and (
            y.val < x.tp.lower or y.val >= x.tp.lower + x.tp.length
          ):
            mark('index out of bounds')
          else:
            x = CG.genIndex(x, y)
        else:
          mark('index not integer')
      else:
        mark('not an array')
      if SC.sym == RBRAK:
        getSym()
      else:
        mark('] expected')
    else:  #  x.f
      getSym()
      if SC.sym == IDENT:
        if type(x.tp) == Record:
          for f in x.tp.fields:
            if f.name == SC.val:
              x = CG.genSelect(x, f)
